ent_id'=>$mockPaymentId,'razorpay_signature'=>$mockSignature],$onlineCsrf);check($status===200&&$verified['order_id']===$onlineOrder['order']['id'],'Razorpay signature verification confirms the online order');$onlinePayment=$db->prepare('SELECT o.status,o.payment_status,p.status AS attempt_status FROM orders o JOIN payment_attempts p ON p.order_id=o.id WHERE o.id=:online_order');$onlinePayment->execute(['online_order'=>$onlineOrder['order']['id']]);$onlinePayment=$onlinePayment->fetch();check($onlinePayment['status']==='confirmed'&&$onlinePayment['payment_status']==='paid'&&$onlinePayment['attempt_status']==='paid','online payment confirmation settles the order exactly once');$onlineRedemptions=$db->prepare('SELECT COUNT(*) FROM coupon_redemptions WHERE coupon_id=:coupon AND user_id=:user AND order_id=:order');$onlineRedemptions->execute(['coupon'=>$couponId,'user'=>$onlineUserId,'order'=>$onlineOrder['order']['id']]);check((int)$onlineRedemptions->fetchColumn()===1,'online payment records the coupon redemption exactly once');
